#include <iostream>
#include <string>
class Base1 {
public:
  std::string data1;
  Base1(const std::string& d) : data1(d) { std::cout << "Base1 constructor called\n"; }
  Base1(Base1&& other) noexcept : data1(std::move(other.data1)) { std::cout << "Base1 move constructor called\n"; }
  Base1& operator=(Base1&& other) noexcept { data1 = std::move(other.data1); std::cout << "Base1 move assignment called\n"; return *this; }
  ~Base1() { std::cout << "Base1 destructor called\n"; }
};
class Base2 {
public:
  std::string data2;
  Base2(const std::string& d) : data2(d) { std::cout << "Base2 constructor called\n"; }
  Base2(Base2&& other) noexcept : data2(std::move(other.data2)) { std::cout << "Base2 move constructor called\n"; }
  Base2& operator=(Base2&& other) noexcept { data2 = std::move(other.data2); std::cout << "Base2 move assignment called\n"; return *this; }
  ~Base2() { std::cout << "Base2 destructor called\n"; }
};
class Derived : public Base1, public Base2 {
public:
  Derived(const std::string& d1, const std::string& d2) : Base1(d1), Base2(d2) { std::cout << "Derived constructor called\n"; }
  Derived(Derived&& other) noexcept : Base1(std::move(other)), Base2(std::move(other)) { std::cout << "Derived move constructor called\n"; }
  Derived& operator=(Derived&& other) noexcept {
    Base1::operator=(std::move(other));
    Base2::operator=(std::move(other));
    std::cout << "Derived move assignment called\n";
    return *this; }
  ~Derived() { std::cout << "Derived destructor called\n";}
};
int main() {
  Derived d1("hello", "world");
  Derived d2 = std::move(d1);
  return 0;
}
